CREATE TABLE IF NOT EXISTS reward_settings (setting_key VARCHAR(48) PRIMARY KEY, value JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_locks (name VARCHAR(32) PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_quest_queue (seq BIGINT AUTO_INCREMENT PRIMARY KEY, event_id CHAR(36) CHARACTER SET ascii NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_login_queue (seq BIGINT AUTO_INCREMENT PRIMARY KEY, event_id CHAR(36) CHARACTER SET ascii NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_boards (day DATE PRIMARY KEY, quests JSON NOT NULL, created_ms BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_progress (player_uuid CHAR(36) CHARACTER SET ascii NOT NULL, day DATE NOT NULL, quest_id VARCHAR(80) NOT NULL, progress BIGINT NOT NULL, target BIGINT NOT NULL, PRIMARY KEY(player_uuid,day,quest_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_mined_positions (day DATE NOT NULL, player_uuid CHAR(36) CHARACTER SET ascii NOT NULL, server_id VARCHAR(96) NOT NULL, world_uuid CHAR(36) CHARACTER SET ascii NOT NULL, x INT NOT NULL,y INT NOT NULL,z INT NOT NULL, PRIMARY KEY(day,player_uuid,server_id,world_uuid,x,y,z)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_placed_positions (server_id VARCHAR(96) NOT NULL,world_uuid CHAR(36) CHARACTER SET ascii NOT NULL,x INT NOT NULL,y INT NOT NULL,z INT NOT NULL, placed_ms BIGINT NOT NULL,PRIMARY KEY(server_id,world_uuid,x,y,z)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_login_days (player_uuid CHAR(36) CHARACTER SET ascii NOT NULL,day DATE NOT NULL,streak INT NOT NULL,reward DECIMAL(18,2) NOT NULL,policy JSON NOT NULL,PRIMARY KEY(player_uuid,day)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_grants (grant_id VARCHAR(160) CHARACTER SET ascii PRIMARY KEY,player_uuid CHAR(36) CHARACTER SET ascii NOT NULL,day DATE NOT NULL,kind VARCHAR(16) NOT NULL,title VARCHAR(200) NOT NULL,amount DECIMAL(18,2) NOT NULL,paid_amount DECIMAL(18,2) NOT NULL DEFAULT 0,paid_ms BIGINT NULL,attempted_ms BIGINT NOT NULL DEFAULT 0,INDEX player_day(player_uuid,day),INDEX pending(paid_ms,attempted_ms)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reward_servers (plugin VARCHAR(32) NOT NULL,server_id VARCHAR(96) NOT NULL,heartbeat_ms BIGINT NOT NULL,last_error VARCHAR(120) NOT NULL,PRIMARY KEY(plugin,server_id)) ENGINE=InnoDB;
